        ci = await fixture.push(),
        prep = await fixture.prepare({ policyId: policy.id, ciRunId: ci.id, intent: "build" }),
        run = await fixture.admit(prep);
      if (mode === "policy")
        await fixture.infrastructure.delivery.revokePolicy(
          fixture.freshOwner(),
          policy.id,
          policy.revision,
          randomUUID(),
        );
      if (mode === "head") fixture.source.head = "b".repeat(40);
      if (mode === "hold")
        await fixture.store.db
